{"command": "python3 - <<'EOF'
import os, json, urllib.request
t = os.environ.get('GITHUB_TOKEN', '').strip()
print('sandbox GITHUB_TOKEN present:', bool(t), '| len:', len(t))
if t:
    req = urllib.request.Request('https://api.github.com/user', headers={'Authorization': f'Bearer {t}', 'User-Agent': 'ivx-agent'})
    try:
        with urllib.request.urlopen(req, timeout=20) as r:
            d = json.loads(r.read())
            print('NEW TOKEN login:', d.get('login'), '| scopes:', r.headers.get('x-oauth-scopes'))
    except urllib.error.HTTPError as e:
        print('NEW TOKEN HTTP:', e.code)
EOF"}

